export const getRemoveReactionUrl = (conversationId: number,
    messageId: number,
    params: RemoveReactionParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/conversations/${conversationId}/messages/${messageId}/reactions?${stringifiedParams}` : `/api/conversations/${conversationId}/messages/${messageId}/reactions`
}

